/**
 * Ultimatum matching API (Google Apps Script)
 * Endpoints:
 *   ?action=claim&pid=PROLIFIC_PID
 *   ?action=complete&pid=PROLIFIC_PID&p1_id=P1_001&token=LOCK_TOKEN
 *
 * Required sheet headers:
 *   p1_id, choice, status, locked_by, locked_at, completed_at, lock_token
 *
 * Optional header:
 *   story
 */

const SHEET_NAME = "pool";
const TIMEOUT_MINUTES = 60;

function doGet(e) {
  try {
    const params = (e && e.parameter) ? e.parameter : {};
    const action = (params.action || "").toLowerCase();

    if (!action) return jsonOut({ ok: false, error: "Missing action" });

    if (action === "claim") return handleClaim_(params);
    if (action === "complete") return handleComplete_(params);

    return jsonOut({ ok: false, error: "Unknown action: " + action });
  } catch (err) {
    return jsonOut({
      ok: false,
      error: String(err),
      stack: err && err.stack ? String(err.stack) : null
    });
  }
}

function handleClaim_(params) {
  const pid = (params.pid || "").trim();
  if (!pid) return jsonOut({ ok: false, error: "Missing pid" });

  const lock = LockService.getScriptLock();
  lock.waitLock(20000);

  try {
    const sheet = SpreadsheetApp.getActive().getSheetByName(SHEET_NAME);
    if (!sheet) return jsonOut({ ok: false, error: "Sheet not found: " + SHEET_NAME });

    const dataRange = sheet.getDataRange();
    const values = dataRange.getValues(); // includes header row

    if (values.length < 2) {
      return jsonOut({ ok: false, error: "No rows in pool" });
    }

    const headers = values[0].map(function(h) {
      return String(h).trim().toLowerCase();
    });
    const col = function(name) {
      return headers.indexOf(name);
    };

    const c_p1 = col("p1_id");
    const c_choice = col("choice");
    const c_story = col("story"); // optional
    const c_status = col("status");
    const c_locked_by = col("locked_by");
    const c_locked_at = col("locked_at");
    const c_completed_at = col("completed_at");
    const c_token = col("lock_token");

    const required = [
      "p1_id",
      "choice",
      "status",
      "locked_by",
      "locked_at",
      "completed_at",
      "lock_token"
    ];

    for (let i = 0; i < required.length; i++) {
      if (col(required[i]) === -1) {
        return jsonOut({ ok: false, error: "Missing required header: " + required[i] });
      }
    }

    // Keep stale-lock recycling logic in case old rows still exist as "locked"
    const now = new Date();
    const timeoutMs = TIMEOUT_MINUTES * 60 * 1000;
    const availableRowIdxs = [];

    for (let i = 1; i < values.length; i++) {
      const status = String(values[i][c_status] || "").toLowerCase().trim();
      const completedAt = values[i][c_completed_at];

      if (status === "locked" && !completedAt) {
        const lockedAt = values[i][c_locked_at];

        if (lockedAt instanceof Date) {
          if (now.getTime() - lockedAt.getTime() > timeoutMs) {
            values[i][c_status] = "available";
            values[i][c_locked_by] = "";
            values[i][c_locked_at] = "";
            values[i][c_token] = "";
          }
        } else {
          values[i][c_status] = "available";
          values[i][c_locked_by] = "";
          values[i][c_locked_at] = "";
          values[i][c_token] = "";
        }
      }

      const statusAfter = String(values[i][c_status] || "").toLowerCase().trim();
      if (statusAfter === "available") {
        availableRowIdxs.push(i);
      }
    }

    if (availableRowIdxs.length === 0) {
      dataRange.setValues(values);
      return jsonOut({ ok: false, error: "No available P1 left (pool exhausted)" });
    }

    // Randomly pick one available row
    const pickIdx = availableRowIdxs[Math.floor(Math.random() * availableRowIdxs.length)];

    const p1_id = String(values[pickIdx][c_p1]).trim();
    const choice = values[pickIdx][c_choice];
    const story = (c_story !== -1) ? values[pickIdx][c_story] : null;
    const token = Utilities.getUuid();

    // Mark as completed immediately
    values[pickIdx][c_status] = "completed";
    values[pickIdx][c_locked_by] = pid;
    values[pickIdx][c_locked_at] = now;
    values[pickIdx][c_token] = token;
    values[pickIdx][c_completed_at] = now;

    dataRange.setValues(values);

    return jsonOut({
      ok: true,
      p1_id: p1_id,
      choice: choice,
      story: story,
      token: token,
      locked_at: now.toISOString(),
      completed_at: now.toISOString(),
      timeout_minutes: TIMEOUT_MINUTES
    });
  } finally {
    lock.releaseLock();
  }
}

function handleComplete_(params) {
  const pid = (params.pid || "").trim();
  const p1_id = (params.p1_id || "").trim();
  const token = (params.token || "").trim();

  if (!pid) return jsonOut({ ok: false, error: "Missing pid" });
  if (!p1_id) return jsonOut({ ok: false, error: "Missing p1_id" });
  if (!token) return jsonOut({ ok: false, error: "Missing token" });

  const lock = LockService.getScriptLock();
  lock.waitLock(20000);

  try {
    const sheet = SpreadsheetApp.getActive().getSheetByName(SHEET_NAME);
    if (!sheet) return jsonOut({ ok: false, error: "Sheet not found: " + SHEET_NAME });

    const dataRange = sheet.getDataRange();
    const values = dataRange.getValues();

    if (values.length < 2) {
      return jsonOut({ ok: false, error: "No rows in pool" });
    }

    const headers = values[0].map(function(h) {
      return String(h).trim().toLowerCase();
    });
    const col = function(name) {
      return headers.indexOf(name);
    };

    const c_p1 = col("p1_id");
    const c_status = col("status");
    const c_locked_by = col("locked_by");
    const c_completed_at = col("completed_at");
    const c_token = col("lock_token");

    const required = ["p1_id", "status", "locked_by", "completed_at", "lock_token"];
    for (let i = 0; i < required.length; i++) {
      if (col(required[i]) === -1) {
        return jsonOut({ ok: false, error: "Missing required header: " + required[i] });
      }
    }

    let rowIdx = -1;
    for (let i = 1; i < values.length; i++) {
      if (String(values[i][c_p1]).trim() === p1_id) {
        rowIdx = i;
        break;
      }
    }

    if (rowIdx === -1) {
      return jsonOut({ ok: false, error: "p1_id not found in pool: " + p1_id });
    }

    // Since rows are already marked completed at claim time,
    // just return success if this same assignment is being referenced.
    const lockedBy = String(values[rowIdx][c_locked_by] || "").trim();
    const storedToken = String(values[rowIdx][c_token] || "").trim();

    if (lockedBy !== pid) {
      return jsonOut({ ok: false, error: "pid mismatch: locked_by=" + lockedBy });
    }
    if (storedToken !== token) {
      return jsonOut({ ok: false, error: "token mismatch" });
    }

    // Ensure completed fields are populated
    values[rowIdx][c_status] = "completed";
    if (!values[rowIdx][c_completed_at]) {
      values[rowIdx][c_completed_at] = new Date();
    }

    dataRange.setValues(values);

    return jsonOut({
      ok: true,
      p1_id: p1_id,
      status: "completed"
    });
  } finally {
    lock.releaseLock();
  }
}

function jsonOut(obj) {
  return ContentService
    .createTextOutput(JSON.stringify(obj))
    .setMimeType(ContentService.MimeType.JSON);
